-- Vorrats-Aufgaben (rollend-11) in bestehende Flüge einfügen: 60 Aufgaben, 17 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (1, 'zahlen.natuerlich', 805, 7, $auf$[{"l": "stellenwert", "t": "stellenwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ich denke mir eine Zahl. Ich hänge hinten drei Nullen an. Dann zähle ich 4 Hunderter dazu und ziehe 7 Zehner ab. Jetzt steht 52 330 da. Welche Zahl habe ich mir gedacht?"}, "o": {"wert": 52}, "h": "Mache die Schritte in umgekehrter Reihenfolge rückgängig. Was bewirkt es, wenn man hinten drei Nullen anhängt?", "w": "Rückwärts: Die 7 Zehner wurden abgezogen, also 70 wieder dazu: 52 330 + 70 = 52 400. Die 4 Hunderter wurden dazugezählt, also 400 wieder weg: 52 400 − 400 = 52 000. Die drei angehängten Nullen entfernt man durch 1 000: 52 000 : 1 000 = 52. Probe: 52 000 + 400 − 70 = 52 330.", "form": "umkehren", "zaehlt": "ja", "r": 11806}, {"l": "ziffern_zu_zahlwort", "t": "ziffern_zu_zahlwort", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim liest die Zahl 30 400 012 in Worten vor. Zeile 1: Von rechts in Dreiergruppen geteilt: 30 | 400 | 012. Zeile 2: Die mittlere Gruppe 400 spricht er als „vierzigtausend“. Zeile 3: Zusammen sagt er: „dreißig Millionen vierzigtausendzwölf“. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Zahl gehört zu dem Zahlwort, das Kim sagt? Vergleiche sie mit der Zahl in Ziffern.", "w": "Die Gruppe 400 steht an der Stelle der Tausender, es sind 400 Tausender, also „vierhunderttausend“. „Vierzigtausend“ wären 40 000. Zeile 3 setzt Kims Wörter richtig zusammen. Richtig gelesen heißt die Zahl „dreißig Millionen vierhunderttausendzwölf“.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11807}, {"l": "strahl_eintragen", "t": "strahl_eintragen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Im Geschichtsraum einer Schule hängt ein Zeitstrahl von 1800 bis 2000. Er ist in 8 gleich lange Abschnitte geteilt, die Teilstriche liegen also gleich weit auseinander. Ein altes Foto der Schule stammt aus dem Jahr 1913 und soll auf dem Strahl eingetragen werden. Wie viele Jahre liegt 1913 vom nächstgelegenen Teilstrich entfernt?"}, "o": {"wert": 12, "einheit": "Jahre"}, "h": "Wie viele Jahre umfasst ein Abschnitt? Schreibe dir die Jahre der Teilstriche auf.", "w": "Ein Abschnitt umfasst (2000 − 1800) : 8 = 25 Jahre. Die Teilstriche liegen bei 1800, 1825, …, 1900, 1925, … 1913 liegt zwischen 1900 (13 Jahre davor) und 1925 (12 Jahre danach). Der nächstgelegene Teilstrich ist 1925, der Abstand beträgt 12 Jahre.", "form": "anwenden", "zaehlt": "ja", "r": 11808}, {"l": "runden_regel", "t": "runden_regel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rundet die Zahl 28 446 auf Hunderter. Er rundet zuerst auf Zehner und dann das Ergebnis auf Hunderter. Zeile 1: Auf Zehner gerundet: 28 446 ≈ 28 450. Zeile 2: Auf Hunderter gerundet: 28 450 ≈ 28 500. Zeile 3: Also ist 28 446 auf Hunderter gerundet 28 500. In welcher Zeile steht zum ersten Mal eine Aussage, die für sich genommen falsch ist?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Runde 28 446 selbst direkt auf Hunderter und vergleiche.", "w": "Zeile 1 und Zeile 2 sind als Aussagen für sich richtig. Falsch ist erst Zeile 3: Man darf nicht in zwei Schritten runden. Bei 28 446 steht rechts neben der Hunderterstelle die 4, also wird abgerundet. Richtig ist 28 400.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11809}, {"l": "runden_sinnvoll", "t": "runden_sinnvoll", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Sportverein erhält in drei Monaten Spenden von 1 452 €, 1 468 € und 1 461 €. Weg A: Jede Spende auf Hunderter runden, dann addieren. Weg B: Erst genau addieren, dann die Summe auf Hunderter runden. Um wie viel Euro liegt das Ergebnis von Weg A weiter vom genauen Betrag entfernt als das Ergebnis von Weg B?"}, "o": {"wert": 100, "einheit": "€"}, "h": "Berechne zuerst den genauen Betrag. Dann beide Wege einzeln.", "w": "Genauer Betrag: 1 452 + 1 468 + 1 461 = 4 381 €. Weg A: jede Spende wird auf 1 500 € gerundet, zusammen 4 500 €. Weg B: 4 381 € wird auf 4 400 € gerundet. Abstand zum genauen Betrag: Weg A 119 €, Weg B 19 €. Der Unterschied ist 119 − 19 = 100 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 11810}, {"l": "roemisch_schreiben", "t": "roemisch_schreiben", "p": "uebung", "s": 3, "g": "transfer", "y": "auswahl", "f": {"text": "Ein Rathaus wurde im Jahr 1897 gebaut. 125 Jahre später wurde es erneuert. Wie schreibt man das Jahr der Erneuerung mit römischen Zeichen?"}, "a": ["MDCCCXCVII", "MCMXXII", "MDCCLXXII", "MMXXII"], "o": {"index": 3}, "h": "Rechne zuerst das Jahr aus. Schreibe es dann Stelle für Stelle, bei den Tausendern beginnend.", "w": "1 897 + 125 = 2 022. Tausender: 2 000 = MM. Zehner: 20 = XX. Einer: 2 = II. Das Jahr 2022 schreibt man MMXXII.", "form": "anwenden", "zaehlt": "ja", "r": 11811}, {"l": "dualsystem", "t": "dualsystem", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Zweierzahl ist 1101101. Weg A: Schreibe die Stellenwerte 64, 32, 16, 8, 4, 2, 1 unter die Ziffern und addiere die Stellenwerte der Einsen. Weg B: Beginne mit der ersten Ziffer. Verdopple bei jeder weiteren Ziffer das bisherige Ergebnis und addiere die neue Ziffer. Welche normale Zahl gehört zur Zweierzahl?"}, "o": {"wert": 109}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Welche Stellen tragen eine 1?", "w": "Weg A: Die Einsen stehen bei 64, 32, 8, 4 und 1: 64 + 32 + 8 + 4 + 1 = 109. Weg B: 1; 1 · 2 + 1 = 3; 3 · 2 + 0 = 6; 6 · 2 + 1 = 13; 13 · 2 + 1 = 27; 27 · 2 + 0 = 54; 54 · 2 + 1 = 109. Die Zahl ist 109.", "form": "zwei_wege", "zaehlt": "ja", "r": 11812}]$auf$::jsonb),
    (3, 'terme.umformen', 777, 3, $auf$[{"l": "produkte", "t": "produkte", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein quaderförmiges Aquarium ist 3a dm lang, 2a dm breit und a dm hoch (a ist eine positive ganze Zahl). Es fasst 48 Liter (1 dm³ ist 1 Liter). Wie viele Dezimeter ist das Aquarium lang?"}, "o": {"wert": 6, "einheit": "dm"}, "h": "Fasse die drei Kantenlängen zu einem Term für das Volumen zusammen. Welchen Wert hat a³? Welche positive ganze Zahl ergibt hoch drei diesen Wert?", "w": "Volumen = 3a · 2a · a = 6a³ dm³. 6a³ = 48 ergibt a³ = 8, also a = 2 (denn 2 · 2 · 2 = 8). Die Länge ist 3a = 3 · 2 = 6 dm. Probe: 6 dm · 4 dm · 2 dm = 48 dm³.", "form": "anwenden", "zaehlt": "ja", "r": 11778}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht 4(2x − 3) − 3(x − 5) − 2(5 − x) in Schritten. Zeile 1: 4(2x − 3) = 8x − 12 Zeile 2: −3(x − 5) = −3x + 15 Zeile 3: −2(5 − x) = −10 − 2x Zeile 4: Zusammen: 8x − 12 − 3x + 15 − 10 − 2x = 3x − 7 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Prüfe jede Zeile mit einer Zahl für x, zum Beispiel x = 1.", "w": "Zeile 1 und 2 stimmen. In Zeile 3 wird −2 mit 5 und mit (−x) multipliziert: −2 · 5 = −10 und −2 · (−x) = +2x. Richtig ist also −10 + 2x. Zeile 4 rechnet mit dem falschen Ergebnis richtig weiter. Mit dem richtigen Wert ergibt sich 7x − 7.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11779}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Terme 4(x + 3) − k(x − 1) und 2x + 14 haben für jede Zahl x denselben Wert. Weg A: Multipliziere den ersten Term aus und vergleiche die Glieder mit x und die Zahlen. Weg B: Setze für x zwei geschickt gewählte Zahlen ein. Welche Zahl ist k?"}, "o": {"wert": 2}, "h": "Beide Wege müssen dasselbe k ergeben. Welche Zahl für x macht die Rechnung besonders einfach? Prüfe das Ergebnis mit einer zweiten Zahl.", "w": "Weg A: 4(x + 3) − k(x − 1) = 4x + 12 − kx + k = (4 − k)x + (12 + k). Vergleich mit 2x + 14: 4 − k = 2 und 12 + k = 14, beides gibt k = 2. Weg B: Für x = 0 ist 12 + k = 14, also k = 2. Zur Kontrolle x = 2: 4 · 5 − 2 · 1 = 18 und 2 · 2 + 14 = 18. Zwei Proben genügen hier, weil beide Terme für ein festes k in x linear sind: Stimmen sie an zwei verschiedenen Stellen überein, dann an jeder.", "form": "zwei_wege", "zaehlt": "ja", "r": 11780}]$auf$::jsonb),
    (5, 'gleichungen.linear', 604, 4, $auf$[{"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 7x − 4 = 3x + 20 und denkt dabei an eine Waage, die im Gleichgewicht bleiben muss. Zeile 1: Auf beiden Seiten 3x wegnehmen: 4x − 4 = 20 Zeile 2: Auf der linken Seite 4 dazulegen: 4x − 4 + 4 = 20, also 4x = 20 Zeile 3: Beide Seiten durch 4 teilen: x = 5 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Setze das Ergebnis in die Gleichung am Anfang ein.", "w": "Zeile 1 stimmt. In Zeile 2 wird nur links 4 dazugelegt. Die Waage kippt: Auch rechts muss 4 dazukommen, also 4x = 24. Zeile 3 rechnet mit der falschen Zeile 2 richtig weiter. Richtig ist x = 6. Probe: 7 · 6 − 4 = 38 und 3 · 6 + 20 = 38.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11605}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Pflanze A ist 12 cm hoch und wächst gleichmäßig 3 cm pro Woche. Eine Pflanze B ist 30 cm hoch und wächst gleichmäßig 1,5 cm pro Woche. Nach einiger Zeit sind beide gleich hoch. Löse die Gleichung und rechne mit der Lösung die Höhe beider Pflanzen aus. Das ist zugleich die Probe. Wie viele Zentimeter sind beide Pflanzen dann hoch?"}, "o": {"wert": 48, "einheit": "cm"}, "h": "Stelle für w Wochen eine Gleichung auf: Höhe von A = Höhe von B. Die Probe: Setze w in beide Höhen ein, beide Werte müssen gleich sein.", "w": "Nach w Wochen: 12 + 3w = 30 + 1,5w. Daraus 1,5w = 18, also w = 12 Wochen. Probe: Pflanze A: 12 + 3 · 12 = 48 cm. Pflanze B: 30 + 1,5 · 12 = 48 cm. Beide sind 48 cm hoch.", "form": "anwenden", "zaehlt": "ja", "r": 11606}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Becken A wird gleichmäßig gefüllt, Becken B wird gleichmäßig leergepumpt. Die Tabelle zeigt die Wassermenge in beiden Becken in Litern. Nach wie vielen Minuten (nach Minute 0) enthalten beide Becken gleich viele Liter?", "grafik": {"typ": "tabelle", "kopf": ["Minute", "0", "1", "2", "3"], "zeilen": [["Wassermenge Becken A in Litern", "12", "20", "28", "36"], ["Wassermenge Becken B in Litern", "82", "76", "70", "64"]]}}, "o": {"wert": 5, "einheit": "min"}, "h": "Wie viele Liter kommen bei A pro Minute dazu, wie viele gehen bei B pro Minute weg? Schreibe beide Wassermengen nach t Minuten als Term.", "w": "Aus der Tabelle: A wächst um 8 Liter pro Minute, B nimmt um 6 Liter pro Minute ab. Nach t Minuten: A = 12 + 8t, B = 82 − 6t. Gleichsetzen: 12 + 8t = 82 − 6t, also 14t = 70 und t = 5. Probe: 12 + 40 = 52 und 82 − 30 = 52.", "form": "bruecke", "zaehlt": "ja", "r": 11607}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Anna hat anfangs 40 € und spart jede Woche 7 €. Ben spart jede Woche 9 €. Nach 8 Wochen haben beide gleich viel Geld. Wie viel Euro hatte Ben am Anfang?"}, "o": {"wert": 24, "einheit": "€"}, "h": "Nenne Bens Anfangsbetrag b. Schreibe auf, wie viel Geld jeder nach 8 Wochen hat. Beide Beträge sind gleich.", "w": "Bens Anfangsbetrag sei b. Nach 8 Wochen hat Anna 40 + 7 · 8 = 96 € und Ben b + 9 · 8 = b + 72 €. Gleichung: b + 72 = 96. Rückwärts gerechnet: b = 96 − 72 = 24 €. Probe: 24 + 72 = 96.", "form": "umkehren", "zaehlt": "ja", "r": 11608}]$auf$::jsonb),
    (7, 'groessen.indirekt', 651, 1, $auf$[{"l": "graph", "t": "darstellen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Der Punkt P(4 | 15) liegt auf dem Graphen einer indirekten Proportionalität (für x > 0). Die Punkte A(10 | a) und B(20 | b) liegen auf demselben Graphen. Weg A: Zeichne auf kariertem Papier P und weitere Punkte des Graphen ein (bestimme dazu das Produkt x · y), skizziere den Ast bis x = 30 und lies a und b bei x = 10 und x = 20 ungefähr ab. Weg B: Rechne a und b exakt aus. Wie groß ist a − b (exakter Wert)?"}, "o": {"wert": 3}, "h": "Beide Wege müssen ungefähr dasselbe ergeben. Bei einer indirekten Proportionalität ist das Produkt x · y für alle Punkte gleich.", "w": "Weg A: x · y = 4 · 15 = 60. Punkte des Graphen: (2 | 30), (3 | 20), (4 | 15), (5 | 12), (6 | 10), (12 | 5), (15 | 4), (30 | 2). Man zeichnet sie, verbindet sie bis x = 30 zu einem Ast und liest bei x = 10 etwa a ≈ 6 und bei x = 20 etwa b ≈ 3 ab. Weg B: exakt a = 60 : 10 = 6 und b = 60 : 20 = 3. Also a − b = 3.", "form": "zwei_wege", "zaehlt": "ja", "r": 11652}]$auf$::jsonb),
    (20, 'gleichungen.bruch', 660, 5, $auf$[{"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Boot fährt auf einem Fluss gegen die Strömung. Die Strömung hat 6 km/h. Das Boot schafft in ruhigem Wasser v km/h und kommt gegen die Strömung voran. Die Fahrzeit für 90 km beträgt 90/(v − 6) Stunden. Die Fahrt dauert 5 Stunden. Wie schnell ist das Boot in ruhigem Wasser?"}, "o": {"wert": 24, "einheit": "km/h"}, "h": "Welche Werte von v sind rechnerisch erlaubt, welche passen zur Sache? Stelle dann die Gleichung auf: Fahrzeit = 5 Stunden.", "w": "Rechnerisch muss der Nenner v − 6 von 0 verschieden sein, also v ≠ 6. Sachlich kommt das Boot nur voran, wenn v > 6 ist. Gleichung: 90/(v − 6) = 5. Mit (v − 6) multiplizieren: 90 = 5(v − 6). Dann 90 : 5 = 18 = v − 6, also v = 24 km/h. Die Lösung 24 erfüllt v > 6. Probe: 90 : (24 − 6) = 90 : 18 = 5 Stunden.", "form": "anwenden", "zaehlt": "ja", "r": 11661}, {"l": "ein_bruch", "t": "ein_bruch", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst (6x + 12)/(3x) = 4 mit x ≠ 0. Zeile 1: Ich kürze mit 3: (6x + 12)/(3x) = (2x + 12)/x, die Gleichung lautet also (2x + 12)/x = 4. Zeile 2: Mit x multiplizieren (x ≠ 0): 2x + 12 = 4x, also 12 = 2x und x = 6. Zeile 3: Die Lösung 6 ist erlaubt, denn 6 ≠ 0. Also ist L = {6}. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Setze die Lösung in die Gleichung am Anfang ein.", "w": "Gekürzt werden darf nur, wenn der ganze Zähler durch 3 geteilt wird: (6x + 12)/(3x) = (2x + 4)/x. In Zeile 1 wurde nur 6x durch 3 geteilt, die 12 blieb stehen. Die Zeilen 2 und 3 rechnen mit der falschen Zeile 1 richtig weiter. Richtig: 2x + 4 = 4x, also x = 2. Probe: (12 + 12)/6 = 4.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11662}, {"l": "hauptnenner", "t": "hauptnenner", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Auto fährt eine Strecke hin mit 60 km/h und denselben Weg zurück mit 40 km/h. Die Länge s der einfachen Strecke ist nicht bekannt. Mit welcher gleichbleibenden Geschwindigkeit v (in km/h) müsste es Hin- und Rückweg fahren, um für beide Wege zusammen genauso lange zu brauchen?"}, "o": {"wert": 48, "einheit": "km/h"}, "h": "Zeit = Weg : Geschwindigkeit. Stelle für beide Fahrten die Gesamtzeit auf und setze die Zeiten gleich.", "w": "Gleichung: s/60 + s/40 = 2s/v. Durch s teilen: 1/60 + 1/40 = 2/v. Mit 120v multiplizieren: 2v + 3v = 240, also 5v = 240 und v = 48 km/h. Probe: Mit s = 120 km: hin 2 h, zurück 3 h, zusammen 5 h; 240 km : 5 h = 48 km/h.", "form": "anwenden", "zaehlt": "ja", "r": 11663}, {"l": "verhaeltnis", "t": "verhaeltnis", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "In einer Mischung ist das Verhältnis Mehl : Zucker = 5 : 2. Nach dem Zugeben von 120 g Zucker ist das Verhältnis Mehl : Zucker = 5 : 4. Stelle mit m für die Mehlmenge eine Verhältnisgleichung auf und löse sie. Wie viel Gramm Mehl sind in der Mischung?"}, "o": {"wert": 300, "einheit": "g"}, "h": "Wie viel Gramm Zucker gehören vorher zu m Gramm Mehl? Wie viel Zucker ist es nachher? Nachher gilt Mehl : Zucker = 5 : 4.", "w": "Mehl m Gramm. Vorher ist der Zucker 2m/5 Gramm, nachher 2m/5 + 120 Gramm. Verhältnisgleichung: m/(2m/5 + 120) = 5/4. Über Kreuz: 4m = 5 · (2m/5 + 120) = 2m + 600, also 2m = 600 und m = 300 g. Kontrolle mit Teilen: Dazugekommen sind 4 − 2 = 2 Teile Zucker, das sind 120 g, ein Teil ist 60 g, Mehl 5 · 60 = 300 g. Probe: Zucker vorher 120 g, nachher 240 g; 300 : 240 = 5 : 4.", "form": "umkehren", "zaehlt": "ja", "r": 11664}, {"l": "graphisch", "t": "graphisch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Gerade y = x + b schneidet den Graphen von y = 12/x an der Stelle x = −4. Sie schneidet ihn noch ein zweites Mal bei einer positiven Zahl x. Bestimme zuerst b. Zeichne dann beide Graphen, lies die positive Schnittstelle ab und kontrolliere sie mit einer Wertetabelle. Wie lautet die x-Koordinate des zweiten Schnittpunkts?"}, "o": {"wert": 3}, "h": "Wie groß ist y = 12/x bei x = −4? Dieser y-Wert muss auch auf der Geraden liegen. Daraus folgt b. Die Schnittstelle liest du dort ab, wo sich beide Graphen treffen.", "w": "Bei x = −4 ist y = 12 : (−4) = −3. Auf der Geraden gilt −3 = −4 + b, also b = 1. Die Gerade ist y = x + 1. Zeichnet man y = 12/x und y = x + 1, so treffen sich die Graphen für x > 0 bei x = 3. Kontrolle mit der Wertetabelle: x = 1: 12 und 2, x = 2: 6 und 3, x = 3: 4 und 4. Einsetzen von x = 3: 12/3 = 4 und 3 + 1 = 4, beide Funktionen haben dort den Wert 4. Der zweite Schnittpunkt liegt bei x = 3.", "form": "umkehren", "zaehlt": "ja", "r": 11665}]$auf$::jsonb),
    (28, 'messen.koerper_darstellung', 589, 3, $auf$[{"l": "prisma", "t": "prisma", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Ecken, Flächen und Kanten gerade Prismen haben, deren Grundfläche ein Vieleck ist. Ein solches Prisma hat 27 Kanten. Wie viele Flächen hat es?", "grafik": {"typ": "tabelle", "kopf": ["Grundfläche", "3-Eck", "4-Eck", "5-Eck", "6-Eck"], "zeilen": [["Ecken", "6", "8", "10", "12"], ["Flächen", "5", "6", "7", "8"], ["Kanten", "9", "12", "15", "18"]]}}, "o": {"wert": 11, "einheit": "Flächen"}, "h": "Suche in der Tabelle ein Muster: Wie hängt die Zahl der Kanten mit der Zahl der Ecken der Grundfläche zusammen?", "w": "In der Tabelle ist die Kantenzahl das Dreifache der Eckenzahl der Grundfläche: 3 · 3 = 9, 3 · 4 = 12, 3 · 5 = 15, 3 · 6 = 18. Bei 27 Kanten hat die Grundfläche 27 : 3 = 9 Ecken. Die Flächenzahl ist immer 2 mehr als die Eckenzahl der Grundfläche (Grund- und Deckfläche kommen zu den Seitenflächen dazu): 9 + 2 = 11 Flächen.", "form": "bruecke", "zaehlt": "ja", "r": 11590}, {"l": "zylinder", "t": "zylinder", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Drei Dosen werden einmal auf dem Tisch abgerollt (eine ganze Umdrehung). Die Tabelle zeigt die Länge der Spur und die Höhe jeder Dose. Zu jeder Dose gehört ein Etikett: Es bedeckt den gesamten Mantel vom unteren bis zum oberen Rand und passt genau einmal rund um die Dose, ohne Überstand. Um wie viele Quadratzentimeter ist das größte Etikett größer als das kleinste?", "grafik": {"typ": "tabelle", "kopf": ["Dose", "A", "B", "C"], "zeilen": [["Spur in cm", "20", "28", "16"], ["Höhe in cm", "9", "7", "12"]]}}, "o": {"wert": 16, "einheit": "cm²"}, "h": "Wie lang ist die Spur im Vergleich zum Rand des Bodens? Welche Form hat ein Etikett, das man glatt auf den Tisch legt?", "w": "Die Spur ist genau so lang wie der Umfang der Grundfläche. Das Etikett ist ein Rechteck mit Länge = Umfang und Breite = Höhe. A: 20 · 9 = 180 cm². B: 28 · 7 = 196 cm². C: 16 · 12 = 192 cm². Größtes Etikett B (196 cm²), kleinstes A (180 cm²): 196 − 180 = 16 cm².", "form": "bruecke", "zaehlt": "ja", "r": 11591}, {"l": "schraegbild", "t": "schraegbild", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Quader ist 8 cm breit und 6 cm hoch. Sein Volumen beträgt 288 cm³. Im Schrägbild wird die Tiefe halb so lang gezeichnet wie in Wirklichkeit. Wie lang ist die nach hinten führende Kante im Schrägbild?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Das Volumen ist Breite · Höhe · Tiefe. Welche Tiefe gehört zum Volumen? Was passiert damit im Bild?", "w": "Volumen = Breite · Höhe · Tiefe, also Tiefe = 288 : (8 · 6) = 288 : 48 = 6 cm. Im Schrägbild wird die Tiefe halbiert: 6 : 2 = 3 cm. Probe: 8 · 6 · 6 = 288.", "form": "umkehren", "zaehlt": "ja", "r": 11592}]$auf$::jsonb),
    (31, 'stochastik.grundbegriffe', 590, 3, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Zwei Glücksräder werden gedreht. Rad A zeigt die Zahlen 1, 2, 3, Rad B zeigt die Zahlen 1, 2, 3, 4. Ein Ergebnis ist ein geordnetes Paar (Zahl auf Rad A | Zahl auf Rad B). Das Ereignis E lautet: „Das Produkt der beiden Zahlen ist eine Primzahl.“ Wie viele Ergebnisse gehören zum Gegenereignis von E?"}, "o": {"wert": 8, "einheit": "Ergebnisse"}, "h": "Wie viele Paare gibt es insgesamt? Finde die Paare, deren Produkt eine Primzahl ist. Das Gegenereignis besteht aus allen anderen Paaren.", "w": "Es gibt 3 · 4 = 12 Paare. Primzahlen als Produkt: (1 | 2) mit 2, (1 | 3) mit 3, (2 | 1) mit 2 und (3 | 1) mit 3. Das sind 4 Paare. Das Gegenereignis von E enthält die übrigen 12 − 4 = 8 Paare. Die 1 ist keine Primzahl.", "form": "bruecke", "zaehlt": "ja", "r": 11591}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Glücksrad wird gedreht. Nach 80 Drehungen ist die relative Häufigkeit von Rot 0,25. Das Rad wird weitergedreht. Nach insgesamt 200 Drehungen ist die relative Häufigkeit von Rot 0,3. Wie oft fiel Rot in den letzten 120 Drehungen?"}, "o": {"wert": 40, "einheit": "mal"}, "h": "Wie oft ist Rot nach 80 Drehungen gefallen? Wie oft nach 200 Drehungen? Aus einer relativen Häufigkeit erhältst du die Anzahl durch Malnehmen mit der Zahl der Drehungen.", "w": "Nach 80 Drehungen: 0,25 · 80 = 20-mal Rot. Nach 200 Drehungen: 0,3 · 200 = 60-mal Rot. In den letzten 120 Drehungen also 60 − 20 = 40-mal. Probe: 20 + 40 = 60 und 60 : 200 = 0,3.", "form": "umkehren", "zaehlt": "ja", "r": 11592}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "In einer Klasse mit 28 Kindern gehen 17 Kinder in den Chor und 15 Kinder in die Theater-AG. Elf der Chorkinder gehen nicht in die Theater-AG. Wie viele Kinder gehen in keine der beiden Gruppen?"}, "o": {"wert": 2, "einheit": "Kinder"}, "h": "Eine Vierfeldertafel mit den Spalten „Chor ja“ und „Chor nein“ und den Zeilen „Theater ja“ und „Theater nein“ kann helfen. Wie viele Chorkinder gehen auch ins Theater?", "w": "Nur Chor: 11 Kinder. Beide: 17 − 11 = 6. Nur Theater: 15 − 6 = 9. Zusammen in mindestens einer Gruppe: 11 + 9 + 6 = 26. Keine der beiden Gruppen: 28 − 26 = 2 Kinder.", "form": "anwenden", "zaehlt": "ja", "r": 11593}]$auf$::jsonb),
    (34, 'terme.bruchterme', 666, 4, $auf$[{"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle zeigt einige Werte des Nenners N(x) = (x − 2)(x + 1)(x − c) für eine feste Zahl c. Der Term T(x) = 7/N(x) hat diesen Nenner. Wie viele Zahlen muss man aus ℚ ausschließen, damit T(x) definiert ist?", "grafik": {"typ": "tabelle", "kopf": ["x", "−2", "−1", "0", "1", "2", "3"], "zeilen": [["N(x)", "−28", "0", "10", "8", "0", "−8"]]}}, "o": {"wert": 3, "einheit": "Zahlen"}, "h": "Mit einem Wert aus der Tabelle kannst du c bestimmen. Wann ist ein Produkt aus drei Faktoren gleich null?", "w": "Für x = 0 ist N(0) = (−2) · 1 · (−c) = 2c. Laut Tabelle ist N(0) = 10, also c = 5. Probe mit x = 1: (−1) · 2 · (1 − 5) = 8, das passt zur Tabelle. Der Nenner ist 0, wenn einer der Faktoren 0 ist: x = 2, x = −1 oder x = 5. Man muss 3 Zahlen ausschließen: D = ℚ \\ {−1; 2; 5}.", "form": "bruecke", "zaehlt": "ja", "r": 11667}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet T(−2) für T(x) = (3 − x²)/(x + 4). Zeile 1: Zähler: (−2)² = −4, also 3 − (−4) = 7 Zeile 2: Nenner: −2 + 4 = 2 Zeile 3: T(−2) = 7 : 2 = 3,5 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Rechne T(−2) selbst mit dem Taschenrechner nach.", "w": "Zeile 1 enthält den Fehler: (−2)² = (−2) · (−2) = 4, nicht −4. Der Zähler ist also 3 − 4 = −1. Zeile 2 stimmt. Zeile 3 rechnet mit dem falschen Zähler 7 richtig weiter. Richtig ist T(−2) = −1 : 2 = −0,5.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11668}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Der Bruch 5/(x − 2) (x ≠ 2 und x ≠ −2) wird so erweitert, dass der Nenner x² − 4 lautet. Weg A: Setze x = 5 in den alten und in den neuen Nenner ein und vergleiche die beiden Zahlen. Weg B: Zerlege x² − 4 mit der dritten binomischen Formel in Faktoren und vergleiche mit dem alten Nenner. Welchen Wert hat der neue Zähler für x = 5?"}, "o": {"wert": 35}, "h": "Beide Wege müssen denselben Wert ergeben. Der Zähler wird mit demselben Faktor malgenommen wie der Nenner.", "w": "Weg A: Für x = 5 ist der alte Nenner 5 − 2 = 3 und der neue Nenner 25 − 4 = 21. Der Nenner wurde mit 21 : 3 = 7 malgenommen, also auch der Zähler: 5 · 7 = 35. Weg B: x² − 4 = (x − 2)(x + 2), der alte Nenner ist ein Faktor davon, der Erweiterungsfaktor ist x + 2, für x = 5 also 7. Neuer Zähler: 5(x + 2) = 5 · 7 = 35. Beide Wege geben 35.", "form": "zwei_wege", "zaehlt": "ja", "r": 11669}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "auswahl", "f": {"text": "Die Tabelle zeigt einige Werte des Terms T(x) = 4/x + 2/(x + 2). Welcher zu einem Bruch zusammengefasste Term gehört zu allen Werten der Tabelle?", "grafik": {"typ": "tabelle", "kopf": ["x", "2", "3", "4"], "zeilen": [["T(x)", "5/2", "26/15", "4/3"]]}}, "a": ["6/(2x + 2)", "(4x + 10)/(x(x + 2))", "(6x + 8)/(x(x + 2))", "6/(x(x + 2))"], "o": {"index": 2}, "h": "Setze einen Wert aus der Tabelle in die Terme ein, zum Beispiel x = 2. Du kannst auch selbst mit dem Hauptnenner x(x + 2) zusammenfassen.", "w": "Hauptnenner x(x + 2): 4/x = 4(x + 2)/(x(x + 2)) und 2/(x + 2) = 2x/(x(x + 2)). Summe: (4x + 8 + 2x)/(x(x + 2)) = (6x + 8)/(x(x + 2)). Probe x = 2: 20/8 = 5/2, das passt zur Tabelle.", "form": "bruecke", "zaehlt": "ja", "r": 11670}]$auf$::jsonb),
    (39, 'zahlen.ganz', 789, 6, $auf$[{"l": "deuten", "t": "verstehen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Möwe fliegt 85 m über dem Meeresspiegel. Ein Fisch schwimmt bei −42 m. Dann steigt die Möwe noch 15 m auf und der Fisch taucht noch 30 m tiefer. Weg A: Rechne die beiden neuen Höhen aus und bilde dann den Höhenunterschied. Weg B: Rechne den Höhenunterschied am Anfang aus und addiere dazu, um wie viel sich beide Tiere voneinander entfernen. Wie viele Meter beträgt der Höhenunterschied zwischen Möwe und Fisch dann?"}, "o": {"wert": 172, "einheit": "m"}, "h": "Beide Wege müssen denselben Höhenunterschied ergeben. Der Höhenunterschied ist die höhere Höhe minus die tiefere Höhe.", "w": "Weg A: Möwe 85 + 15 = 100 m, Fisch −42 − 30 = −72 m. Höhenunterschied: 100 − (−72) = 100 + 72 = 172 m. Weg B: Am Anfang 85 − (−42) = 127 m. Die Möwe steigt 15 m, der Fisch taucht 30 m, zusammen wächst der Unterschied um 45 m: 127 + 45 = 172 m. Beide Wege ergeben 172 m.", "form": "zwei_wege", "zaehlt": "ja", "r": 11790}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle zeigt die Kontostände von fünf Personen. Ordne die Stände gedanklich auf einer Zahlengerade von links nach rechts. Wie viele Euro liegen zwischen dem zweitniedrigsten und dem zweithöchsten Stand?", "grafik": {"typ": "tabelle", "kopf": ["Person", "Ali", "Bea", "Cem", "Dora", "Emil"], "zeilen": [["Stand in €", "−35", "20", "−80", "5", "−12"]]}}, "o": {"wert": 40, "einheit": "€"}, "h": "Welche Zahl liegt auf der Zahlengerade am weitesten links, welche als Nächstes? Mit negativen Zahlen kommt es nicht auf die Größe der Ziffer an.", "w": "Von links nach rechts: −80, −35, −12, 5, 20. Der zweitniedrigste Stand ist −35 €, der zweithöchste ist 5 €. Zwischen ihnen liegen 5 − (−35) = 40 €.", "form": "bruecke", "zaehlt": "ja", "r": 11791}, {"l": "schriftlich_plus_minus", "t": "schriftlich", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim addiert schriftlich 3 748 + 2 659 + 1 875 und rechnet von rechts nach links. Zeile 1: Einer: 8 + 9 + 5 = 22. Ich schreibe 2 hin und merke 1. Zeile 2: Zehner: 4 + 5 + 7 + 1 = 17. Ich schreibe 7 hin und merke 1. Zeile 3: Hunderter: 7 + 6 + 8 + 1 = 22. Ich schreibe 2 hin und merke 2. Zeile 4: Tausender: 3 + 2 + 1 + 2 = 8. Ich schreibe 8 hin. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 0}, "h": "Prüfe jede Zeile: Passen Summe, hingeschriebene Ziffer und gemerkter Übertrag zusammen?", "w": "Die Summe in Zeile 1 stimmt: 8 + 9 + 5 = 22. Aber bei 22 muss man 2 merken (zwei Zehner), nicht 1. Alle weiteren Zeilen rechnen mit dem falschen Übertrag richtig weiter. Richtig wäre: Zehner 4 + 5 + 7 + 2 = 18 (schreibe 8, merke 1), Hunderter 7 + 6 + 8 + 1 = 22 (schreibe 2, merke 2), Tausender 3 + 2 + 1 + 2 = 8. Ergebnis: 8 282, Kim erhält 8 272.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11792}, {"l": "subtrahieren", "t": "subtrahieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ich denke mir eine ganze Zahl. Davon ziehe ich −9 ab, dann ziehe ich 14 ab, und dann addiere ich −5. Ich erhalte −21. Wie heißt meine Zahl?"}, "o": {"wert": -11}, "h": "Mache jeden Schritt in umgekehrter Reihenfolge rückgängig. Was hebt „minus −9“ auf?", "w": "Rückwärts, mit dem letzten Schritt zuerst: −21 − (−5) = −16. Dann −16 + 14 = −2. Dann −2 + (−9) = −11. Probe: −11 − (−9) = −2; −2 − 14 = −16; −16 + (−5) = −21. Die Zahl ist −11.", "form": "umkehren", "zaehlt": "ja", "r": 11793}, {"l": "ketten", "t": "verbinden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet −14 − (−9) + (−6) − (8 − 21) in Teilschritten. Zeile 1: Die ersten drei Zahlen: −14 − (−9) + (−6) = −14 + 9 − 6 = −11 Zeile 2: Die Klammer: 8 − 21 = −13 Zeile 3: Zusammen: −11 − (−13) = −11 − 13 = −24 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Rechne jede Zeile einzeln nach.", "w": "Zeile 1 und Zeile 2 stimmen. In Zeile 3 steht „− (−13)“. Das heißt „plus 13“, nicht „minus 13“. Richtig: −11 + 13 = 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11794}, {"l": "sach", "t": "verbinden", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Der Pegel eines Baches steht am Montagmorgen bei −35 cm (Nullmarke ist 0). Montag steigt er um 60 cm, Dienstag fällt er um 45 cm, Mittwoch steigt er um 25 cm, Donnerstag fällt er um 80 cm, Freitag steigt er um 38 cm. Weg A: Verfolge den Pegel Tag für Tag. Weg B: Zähle alle Anstiege zusammen und alle Rückgänge zusammen und vergleiche beides mit dem Start. Welchen Pegel zeigt die Messlatte am Freitagabend in cm?"}, "o": {"wert": -37, "einheit": "cm"}, "h": "Beide Wege müssen dasselbe ergeben. Vergiss nicht, wo der Pegel am Montagmorgen steht.", "w": "Weg A: −35 + 60 = 25; 25 − 45 = −20; −20 + 25 = 5; 5 − 80 = −75; −75 + 38 = −37. Weg B: Anstiege 60 + 25 + 38 = 123 cm, Rückgänge 45 + 80 = 125 cm, Bilanz −2 cm. −35 + (−2) = −37. Der Pegel steht bei −37 cm.", "form": "zwei_wege", "zaehlt": "ja", "r": 11795}]$auf$::jsonb),
    (41, 'zahlen.potenzen_basis', 558, 3, $auf$[{"l": "berechnen", "t": "berechnen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Zellen eine Kultur nach 2 und nach 5 Stunden hat. In jeder Stunde wird die Zahl der Zellen mit derselben Zahl malgenommen. Wie viele Zellen sind es nach 7 Stunden?", "grafik": {"typ": "tabelle", "kopf": ["Stunden", "2", "5"], "zeilen": [["Zellen", "9", "243"]]}}, "o": {"wert": 2187, "einheit": "Zellen"}, "h": "Wie oft wird zwischen Stunde 2 und Stunde 5 mit derselben Zahl malgenommen? Welche Zahl ist es? Schreibe die Zahlen als Potenzen.", "w": "Von Stunde 2 bis Stunde 5 sind es 3 Schritte: 243 : 9 = 27 = 3 · 3 · 3, die Zahl ist also mit 3 malgenommen worden. Dann ist 9 = 3², und nach n Stunden sind es 3ⁿ Zellen. Nach 7 Stunden: 3⁷ = 2 187 Zellen. Kontrolle: 243 · 3 · 3 = 2 187.", "form": "bruecke", "zaehlt": "ja", "r": 11559}, {"l": "vertauschen", "t": "begriff", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Zahlenschloss hat 4 Rädchen. Jedes Rädchen hat 6 Stellungen. Kim zählt, wie viele Einstellungen es gibt. Zeile 1: Bei 4 Rädchen mit je 6 Stellungen gibt es 4⁶ Einstellungen (Basis 4, Hochzahl 6). Zeile 2: 4⁶ = 4 · 4 · 4 · 4 · 4 · 4 = 4 096. Zeile 3: Das Schloss hat also 4 096 Einstellungen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Überlege mit 2 Rädchen: Wie viele Einstellungen gibt es dann?", "w": "Mit 2 Rädchen gäbe es 6 · 6 = 36 Einstellungen. Jedes Rädchen bringt den Faktor 6, und es gibt 4 Rädchen: Richtig ist 6⁴ = 1 296. In Zeile 1 sind Basis und Hochzahl vertauscht. Zeile 2 rechnet 4⁶ richtig aus, Zeile 3 folgt daraus.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11560}, {"l": "negativ", "t": "negativ", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Bei einem Spiel wird der Punktestand nach jeder Runde mit (−2) malgenommen. Du startest mit 3 Punkten. Wie viele Punkte hast du nach 5 Runden?"}, "o": {"wert": -96, "einheit": "Punkte"}, "h": "Schreibe die 5 Runden als Potenz. Wie oft kommt der Faktor (−2) vor, und was bedeutet das für das Vorzeichen?", "w": "Nach 5 Runden wurde 5-mal mit (−2) malgenommen: 3 · (−2)⁵. (−2)⁵ = −32, denn bei einer ungeraden Zahl von Faktoren bleibt das Minus stehen. 3 · (−32) = −96 Punkte.", "form": "anwenden", "zaehlt": "ja", "r": 11561}]$auf$::jsonb),
    (44, 'zahlen.rechengesetze', 890, 6, $auf$[{"l": "klammern", "t": "vorrang", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "auswahl", "f": {"text": "Die Tabelle beschreibt eine Rechenmaschine. Sie führt die Schritte nacheinander aus, jeweils mit dem Ergebnis des Schritts davor. Welcher Term gibt genau das Ergebnis der Maschine an?", "grafik": {"typ": "tabelle", "kopf": ["Schritt", "1", "2", "3", "4", "5"], "zeilen": [["Rechnung", "Start mit 20", "plus 10", "mal 3", "minus 15", "geteilt durch 5"]]}}, "a": ["20 + 10 · 3 − 15 : 5", "(20 + 10) · 3 − 15 : 5", "((20 + 10) · 3 − 15) : 5", "20 + 10 · (3 − 15 : 5)"], "o": {"index": 2}, "h": "Rechne zuerst die Maschine Schritt für Schritt aus. Prüfe dann, welcher Term durch seine Klammern dieselbe Reihenfolge erzwingt.", "w": "Die Maschine rechnet: 20 + 10 = 30; 30 · 3 = 90; 90 − 15 = 75; 75 : 5 = 15. Der Term ((20 + 10) · 3 − 15) : 5 hat dieselbe Reihenfolge und ergibt 15. Ohne Klammern gilt Punkt vor Strich, dann ändert sich die Reihenfolge.", "form": "bruecke", "zaehlt": "ja", "r": 11891}, {"l": "vorteil", "t": "gesetze", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ich denke mir eine Zahl. Ich multipliziere sie mit 25, dann mit 4 und addiere zum Schluss 17. Das Ergebnis ist 2 317. Welche Zahl habe ich mir gedacht?"}, "o": {"wert": 23}, "h": "Mache die Schritte in umgekehrter Reihenfolge rückgängig.", "w": "Rückwärts: 2 317 − 17 = 2 300. Das Malnehmen mit 25 und mit 4 ist zusammen ein Malnehmen mit 100. Also 2 300 : 100 = 23. Probe: 23 · 25 = 575, 575 · 4 = 2 300, 2 300 + 17 = 2 317.", "form": "umkehren", "zaehlt": "ja", "r": 11892}, {"l": "verteilen", "t": "gesetze", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet mit dem Verteilungsgesetz. Zeile 1: (84 + 12) : 6 = 84 : 6 + 12 : 6 Zeile 2: 84 : (3 + 4) = 84 : 3 + 84 : 4 Zeile 3: 84 : 3 + 84 : 4 = 28 + 21 = 49 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne beide Seiten jeder Gleichung getrennt aus.", "w": "Zeile 1 stimmt: Beim Teilen darf man eine Summe im Dividenden verteilen. In Zeile 2 steht die Summe aber im Teiler. Das darf man nicht verteilen: 84 : (3 + 4) = 84 : 7 = 12, aber 28 + 21 = 49. Zeile 3 rechnet mit der falschen Zeile 2 richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11893}, {"l": "mal_ganz", "t": "ganz", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Tauchroboter sinkt gleichmäßig. Seine Höhe ändert sich jede Minute um −4 m (Meeresspiegel = 0 m). Jetzt befindet er sich bei −26 m. In welcher Höhe in Metern war er vor 5 Minuten?"}, "o": {"wert": -6, "einheit": "m"}, "h": "Vor 5 Minuten heißt: Die Zeit ist −5 Minuten. Wie ändert sich die Höhe in dieser Zeit?", "w": "Vor 5 Minuten war die Zeit −5 Minuten. Die Höhenänderung ist (−4) · (−5) = +20 m. Höhe damals: −26 + 20 = −6 m. Probe: Von −6 m sinkt er in 5 Minuten um 20 m auf −26 m.", "form": "anwenden", "zaehlt": "ja", "r": 11894}, {"l": "umkehraufgabe_mal", "t": "gleichungen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ich denke mir eine ganze Zahl. Ich multipliziere sie mit (−6) und ziehe 15 ab. Dann teile ich durch (−3). Ich erhalte 11. Welche Zahl habe ich mir gedacht?"}, "o": {"wert": 3}, "h": "Beginne mit dem letzten Schritt und kehre jeden Schritt um. Was ist die Umkehrung von „geteilt durch −3“?", "w": "Rückwärts: Die Umkehrung von „: (−3)“ ist „· (−3)“: 11 · (−3) = −33. Die Umkehrung von „− 15“ ist „+ 15“: −33 + 15 = −18. Die Umkehrung von „· (−6)“ ist „: (−6)“: (−18) : (−6) = 3. Probe: 3 · (−6) = −18; −18 − 15 = −33; (−33) : (−3) = 11.", "form": "umkehren", "zaehlt": "ja", "r": 11895}, {"l": "schriftlich", "t": "verfahren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Das Malgitter gehört zu einer schriftlichen Multiplikation. Die Zahlen am Rand fehlen, das Feld unten rechts ist verdeckt. Die linke Spalte gehört zum Zehnerwert des zweiten Faktors, die rechte Spalte zum Einerwert. Kim rechnet dieselbe Aufgabe schriftlich. Seine erste Zeile (die Multiplikation mit dem Zehnerwert) ergibt 1 380. Welche Zahl gehört in das Feld mit dem Fragezeichen?", "grafik": {"typ": "tabelle", "kopf": ["Feld", "linke Spalte", "rechte Spalte"], "zeilen": [["oben", "1 200", "320"], ["unten", "?", "verdeckt"]]}}, "o": {"wert": 180}, "h": "Welche Felder des Gitters gehören zu Kims erster Zeile? Was muss ihre Summe ergeben?", "w": "Kims erste Zeile ist die Summe der Felder der linken Spalte: 1 200 + ? = 1 380. Also ist ? = 1 380 − 1 200 = 180. Die rechte Spalte (320 und 48) gehört zur zweiten Zeile, der Multiplikation mit dem Einerwert.", "form": "bruecke", "zaehlt": "ja", "r": 11896}]$auf$::jsonb),
    (53, 'stochastik.kombinatorik', 533, 4, $auf$[{"l": "systematisch", "t": "systematisch", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Aus den Ziffern 1, 2, 3, 4 und 5 werden zweistellige Zahlen mit zwei verschiedenen Ziffern gebildet. Weg A: Schreibe alle diese Zahlen systematisch auf und zähle die passenden. Weg B: Zähle getrennt die Zahlen mit zwei ungeraden Ziffern und die Zahlen mit zwei geraden Ziffern. Wie viele der Zahlen haben eine gerade Quersumme?"}, "o": {"wert": 8}, "h": "Beide Wege müssen dieselbe Anzahl ergeben. Welche der Ziffern sind gerade, welche ungerade?", "w": "Weg A: Passend sind 13, 15, 31, 35, 51, 53 (zwei ungerade Ziffern) und 24, 42 (zwei gerade Ziffern): 8 Zahlen. Weg B: Zwei ungerade Ziffern aus 1, 3, 5: 3 · 2 = 6 Zahlen. Zwei gerade Ziffern aus 2, 4: 2 · 1 = 2 Zahlen. Zusammen 6 + 2 = 8. Bei einer geraden und einer ungeraden Ziffer ist die Quersumme ungerade.", "form": "zwei_wege", "zaehlt": "ja", "r": 11534}, {"l": "reihenfolgen", "t": "reihenfolgen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Fünf verschiedene Kinder stellen sich in einer Reihe auf. Die 3 Mädchen stehen auf den Plätzen 1 bis 3, die 2 Jungen auf den Plätzen 4 und 5. Kim zählt die möglichen Reihenfolgen. Zeile 1: Für die Mädchen gibt es auf den Plätzen 1 bis 3 genau 3 · 2 · 1 = 6 Möglichkeiten. Zeile 2: Für die Jungen gibt es auf den Plätzen 4 und 5 genau 2 · 1 = 2 Möglichkeiten. Zeile 3: Zu jeder der 6 Anordnungen der Mädchen gibt es alle 2 Anordnungen der Jungen. Zeile 4: Die Möglichkeiten der Mädchen und der Jungen werden zusammengezählt: 6 + 2 = 8 Reihenfolgen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Prüfe jede Zeile einzeln. Passt die Rechenart zur Frage?", "w": "Zeile 1 bis 3 stimmen. Weil zu jeder der 6 Anordnungen der Mädchen jede der 2 Anordnungen der Jungen passt, muss man malnehmen: 6 · 2 = 12 Reihenfolgen. In Zeile 4 wird stattdessen 6 + 2 = 8 gerechnet.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11535}, {"l": "baumdiagramm", "t": "baumdiagramm", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Bei einem Schulfest wählt jedes Kind zuerst ein Hauptgericht. Zur Wahl stehen Nudeln (dazu 3 Soßen zur Wahl), Reis (dazu 2 Soßen) und Kartoffeln (dazu 4 Soßen). Danach wählt jedes Kind noch einen Nachtisch aus 2 Sorten, bei jedem Hauptgericht dieselben zwei. Ein Menü besteht aus Hauptgericht, Soße und Nachtisch. Wie viele verschiedene Menüs sind möglich?"}, "o": {"wert": 18, "einheit": "Menüs"}, "h": "Zeichne die Äste für das Hauptgericht. Bei den Soßen ist die Zahl der Äste nicht bei jedem Ast gleich.", "w": "Baumdiagramm: Nudeln hat 3 Soßen, Reis 2, Kartoffeln 4. Das sind 3 + 2 + 4 = 9 Wege bis zur Soße. Jeder dieser Wege teilt sich in 2 Nachtische: 9 · 2 = 18 Menüs. Man kann auch rechnen: 3 · 2 + 2 · 2 + 4 · 2 = 6 + 4 + 8 = 18.", "form": "anwenden", "zaehlt": "ja", "r": 11536}, {"l": "bedingungen", "t": "bedingungen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Zahlencode besteht nur aus Ziffern von 0 bis 9. Die erste Ziffer darf nicht 0 sein, die übrigen Ziffern sind beliebig und dürfen sich wiederholen. Alle Codes sind gleich lang. Es gibt insgesamt 90 000 mögliche Codes. Wie viele Ziffern hat ein Code?"}, "o": {"wert": 5}, "h": "Wie viele Möglichkeiten hat die erste Ziffer? Wie viele hat jede weitere Ziffer?", "w": "Für die erste Ziffer gibt es 9 Möglichkeiten (1 bis 9). 90 000 : 9 = 10 000 = 10 · 10 · 10 · 10: Die übrigen Ziffern haben je 10 Möglichkeiten, und es sind 4 solche Stellen. Zusammen mit der ersten Ziffer hat der Code 5 Ziffern. Probe: 9 · 10 · 10 · 10 · 10 = 90 000.", "form": "umkehren", "zaehlt": "ja", "r": 11537}]$auf$::jsonb),
    (72, 'terme.quadratische_extreme', 390, 1, $auf$[{"l": "scheitelform", "t": "scheitelform", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Hersteller berechnet seine Kosten mit K(x) = x² − 12x + 50. Dabei ist x die Produktmenge in Hundert Stück und K(x) sind die Kosten in Hundert Euro. Wie viel Euro betragen die kleinsten möglichen Kosten?"}, "o": {"wert": 1400, "einheit": "€"}, "h": "Forme K(x) mit quadratischer Ergänzung in die Scheitelform um. Der kleinste Wert steht im Scheitel. Beachte die Einheit „Hundert Euro“.", "w": "x² − 12x + 50 = (x − 6)² − 36 + 50 = (x − 6)² + 14. Das Quadrat ist nie negativ, der kleinste Wert ist 14 und wird bei x = 6 erreicht. 14 Hundert Euro sind 1 400 €. Probe: K(6) = 36 − 72 + 50 = 14.", "form": "anwenden", "zaehlt": "ja", "r": 11391}]$auf$::jsonb),
    (94, 'messen.prisma_zylinder', 411, 2, $auf$[{"l": "prisma_volumen", "t": "prisma_volumen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein gerades Prisma hat als Grundfläche ein rechtwinkliges Dreieck. Die Tabelle zeigt das Volumen des Prismas bei verschiedenen Körperhöhen. Eine Kathete des Dreiecks ist 5 cm lang. Wie lang ist die andere Kathete?", "grafik": {"typ": "tabelle", "kopf": ["Körperhöhe in cm", "2", "4", "6", "8"], "zeilen": [["Volumen in cm³", "30", "60", "90", "120"]]}}, "o": {"wert": 6, "einheit": "cm"}, "h": "Das Volumen ist Grundfläche mal Körperhöhe. Wie groß muss die Grundfläche sein, damit die Tabelle stimmt? Wie berechnet man die Fläche eines rechtwinkligen Dreiecks?", "w": "Aus der Tabelle: V : h = 30 : 2 = 15, ebenso 60 : 4 = 15 usw. Die Grundfläche ist also 15 cm². Für ein rechtwinkliges Dreieck gilt G = Kathete · Kathete : 2. Also 5 · k : 2 = 15, 5 · k = 30 und k = 6 cm.", "form": "bruecke", "zaehlt": "ja", "r": 11412}, {"l": "zylinder_oberflaeche", "t": "zylinder_oberflaeche", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein gerader Zylinder hat den Radius 5 cm. Seine Oberfläche (Mantel, Boden und Deckel) beträgt 150π cm². Wie hoch ist der Zylinder?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Die Oberfläche ist 2πr² + 2πrh. Teile beide Seiten durch π und ziehe dann das Stück für Boden und Deckel ab.", "w": "O = 2πr² + 2πrh = 2πr(r + h). Mit r = 5: 150π = 10π(5 + h). Durch 10π teilen: 15 = 5 + h, also h = 10 cm. Probe: 2π · 25 + 2π · 5 · 10 = 50π + 100π = 150π.", "form": "umkehren", "zaehlt": "ja", "r": 11413}]$auf$::jsonb),
    (111, 'terme.potenzgesetze_natuerlich', 166, 2, $auf$[{"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Berechne 2⁷ · 5⁷ − 2⁶ · 5⁶. Weg A: Rechne alle vier Potenzen einzeln aus und dann weiter. Weg B: Nimm in jedem Produkt zuerst die Basen mal, weil die Hochzahlen gleich sind. Welchen Wert hat der Term?"}, "o": {"wert": 9000000}, "h": "Beide Wege müssen denselben Wert ergeben. Welche Basis entsteht, wenn man 2 und 5 malnimmt?", "w": "Weg B: 2⁷ · 5⁷ = (2 · 5)⁷ = 10⁷ = 10 000 000 und 2⁶ · 5⁶ = 10⁶ = 1 000 000. Differenz: 9 000 000. Weg A: 2⁷ = 128, 5⁷ = 78 125, 128 · 78 125 = 10 000 000; 2⁶ = 64, 5⁶ = 15 625, 64 · 15 625 = 1 000 000. Gleiches Ergebnis.", "form": "zwei_wege", "zaehlt": "ja", "r": 11167}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht (a²)³ · a⁴ für eine Zahl a ≠ 0. Zeile 1: (a²)³ = a⁶, denn 2 · 3 = 6. Zeile 2: a⁶ · a⁴ = a²⁴, denn ich multipliziere 6 und 4. Zeile 3: Also ist (a²)³ · a⁴ = a²⁴ In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe jede Zeile mit a = 2.", "w": "Zeile 1 stimmt: Bei einer Potenz von einer Potenz werden die Hochzahlen malgenommen. In Zeile 2 steht aber ein Produkt gleicher Basen: Dort werden die Hochzahlen addiert, also a⁶ · a⁴ = a¹⁰. Zeile 3 folgt aus der falschen Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11168}]$auf$::jsonb),
    (112, 'terme.potenzgesetze_ganzzahlig', 112, 3, $auf$[{"l": "warum_gilt", "t": "warum_gilt", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim setzt das Muster der Zweierpotenzen nach rechts fort. Bei jedem Schritt nach rechts wird durch 2 geteilt. Zeile 1: 2⁴ = 16, 2³ = 8, 2² = 4, 2¹ = 2 Zeile 2: 2⁰ = 2 : 2 = 1 Zeile 3: 2⁻¹ = 1 : 2 = 1/2 Zeile 4: 2⁻² = 1/2 − 2 = −3/2 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Welche Rechenart steht bei jedem Schritt nach rechts? Rechne jede Zeile nach.", "w": "Zeile 1 bis 3 stimmen. In Zeile 4 wird 2 abgezogen statt geteilt. Das Muster verlangt aber: 1/2 : 2 = 1/4. Also ist 2⁻² = 1/4, und eine negative Hochzahl macht die Potenz nicht negativ.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11113}, {"l": "gleiche_basis_ganz", "t": "gleiche_basis_ganz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht (a ≠ 0) den Term a⁻⁴ · a⁷ : a⁻² · a⁻⁵. Zeile 1: a⁻⁴ · a⁷: Die Hochzahlen werden addiert, (−4) + 7 = 3. Also ist a⁻⁴ · a⁷ = a³. Zeile 2: a³ : a⁻²: Die Hochzahlen werden subtrahiert, 3 − (−2) = 5. Also ist a³ : a⁻² = a⁵. Zeile 3: a⁵ · a⁻⁵: Die Hochzahlen werden addiert, 5 + (−5) = 0. Also ist a⁵ · a⁻⁵ = a⁰ = 0. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Rechne jede Zeile mit einer Zahl nach, zum Beispiel a = 2.", "w": "Zeile 1 und 2 stimmen. In Zeile 3 ist die Hochzahl 5 + (−5) = 0 richtig, aber a⁰ ist 1 (für a ≠ 0), nicht 0. Man kann auch sehen: a⁵ · a⁻⁵ = a⁵ · 1/a⁵ = 1. Richtig ist das Ergebnis 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 11114}, {"l": "exponent_und_potenz", "t": "exponent_und_potenz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Berechne (2⁻²)⁻³ · 2⁻⁴. Weg A: Verrechne die Hochzahlen mit den Potenzgesetzen und rechne dann die eine Potenz aus. Weg B: Schreibe die Potenzen mit negativer Hochzahl als Brüche und rechne mit den Brüchen. Welchen Wert hat der Term?"}, "o": {"wert": 4}, "h": "Beide Wege müssen denselben Wert ergeben. Bei einer Potenz von einer Potenz werden die Hochzahlen malgenommen, bei einem Produkt gleicher Basen addiert.", "w": "Weg A: Die Hochzahlen werden multipliziert: (−2) · (−3) = 6. Also ist (2⁻²)⁻³ = 2⁶. Dann werden bei 2⁶ · 2⁻⁴ die Hochzahlen addiert: 6 + (−4) = 2, also 2² = 4. Weg B: 2⁻² = 1/4. (1/4)⁻³ = 4³ = 64. 2⁻⁴ = 1/16. 64 · 1/16 = 4. Beide Wege: 4.", "form": "zwei_wege", "zaehlt": "ja", "r": 11115}]$auf$::jsonb),
    (305, 'terme.umformen_teil2', 789, 3, $auf$[{"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Das Produkt (x + p)(x − 5) ergibt ausgemultipliziert und zusammengefasst x² + 2x − 35, und das gilt für jede Zahl x. Welche Zahl ist p?"}, "o": {"wert": 7}, "h": "Multipliziere (x + p)(x − 5) allgemein aus. Welche Glieder müssen mit x und welche ohne x übereinstimmen?", "w": "(x + p)(x − 5) = x² − 5x + px − 5p = x² + (p − 5)x − 5p. Vergleich mit x² + 2x − 35: p − 5 = 2, also p = 7. Kontrolle am Zahlenglied: −5p = −35 gilt für p = 7.", "form": "umkehren", "zaehlt": "ja", "r": 11790}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Rechteck besteht aus zwei Teilrechtecken nebeneinander, die dieselbe Höhe h haben. Die Tabelle zeigt ihre Flächeninhalte (x ist eine positive Zahl ohne Einheit, die Flächen sind in cm² angegeben). Als Höhe h wird der größte gemeinsame Faktor beider Flächeninhalte gewählt (mit Zahl und x). Wie breit ist das ganze Rechteck für x = 4 (in cm)?", "grafik": {"typ": "tabelle", "kopf": ["Teilrechteck", "links", "rechts"], "zeilen": [["Flächeninhalt", "10x² cm²", "15x cm²"]]}}, "o": {"wert": 11, "einheit": "cm"}, "h": "Welche Zahl und welche Potenz von x teilt beide Flächeninhalte? Die Breite eines Teils ist Fläche geteilt durch Höhe.", "w": "Gemeinsamer Faktor von 10x² und 15x ist 5x. Die Höhe ist 5x cm. Breite links: 10x² : 5x = 2x cm. Breite rechts: 15x : 5x = 3 cm. Gesamtbreite (2x + 3) cm. Für x = 4: 2 · 4 + 3 = 11 cm. Probe: Fläche 5x(2x + 3) = 20 · 11 = 220 und 10 · 16 + 15 · 4 = 220.", "form": "bruecke", "zaehlt": "ja", "r": 11791}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Berechne 97² − 96 · 98 auf zwei Wegen. Weg A: Rechne 97² mit der zweiten binomischen Formel als (100 − 3)² und 96 · 98 als (100 − 4)(100 − 2) einzeln aus. Weg B: Schreibe 96 als 97 − 1 und 98 als 97 + 1 und benutze die dritte binomische Formel. Welchen Wert hat der Term?"}, "o": {"wert": 1}, "h": "Beide Wege müssen dasselbe ergeben. Die zweite binomische Formel hat in der Mitte das Glied −2ab.", "w": "Weg A: (100 − 3)² = 10 000 − 600 + 9 = 9 409. (100 − 4)(100 − 2) = 10 000 − 200 − 400 + 8 = 9 408. Differenz 9 409 − 9 408 = 1. Weg B: 96 · 98 = (97 − 1)(97 + 1) = 97² − 1². Also 97² − 96 · 98 = 97² − (97² − 1) = 1.", "form": "zwei_wege", "zaehlt": "ja", "r": 11792}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 60 then fehler := fehler || ('zusammen ' || gesamt || ' statt 60')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (1, 3, 5, 7, 20, 28, 31, 34, 39, 41, 44, 53, 72, 94, 111, 112, 305) group by 1 order by 1;
